app_header_box.css:
.app-header-box {
  display: flex; align-items: center; gap: 1.25rem; padding: 1.25rem;
  background: #ffffff; border-radius: 20px; border: 1px solid #e0e0e0;
  margin-bottom: 2rem; box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}
.app-icon-wrapper { flex-shrink: 0; }
.app-icon-wrapper img {
  width: 80px !important; height: 80px !important; object-fit: cover !important;
  border-radius: 22%; display: block !important; margin: 0 !important;
}
.app-info-wrapper h1.app-title { font-size: 1.4rem !important; font-weight: 800 !important; margin: 0 !important; color: #202124; line-height: 1.2; }
.app-info-wrapper .app-meta { font-size: 0.85rem; color: #5f6368; margin-top: 0.3rem; display: flex; gap: 10px; }

app_specs_table.css:
.app-specs-table { width: 100%; background: #ffffff; border-radius: 12px; border: 1px solid #eee; margin: 1.5rem 0; overflow: hidden; }
.app-specs-table .spec-row { display: flex; justify-content: space-between; padding: 0.75rem 1rem; border-bottom: 1px solid #f8f9fa; }
.app-specs-table .spec-row:last-child { border-bottom: none; }
.app-specs-table .spec-label { font-weight: 600; color: #5f6368; font-size: 0.85rem; text-transform: uppercase; }
.app-specs-table .spec-value { color: #202124; font-size: 0.9rem; font-weight: 500; }

download_section.css:
.download-section { display: flex; flex-direction: column; gap: 12px; margin: 2rem 0; }
.btn-app-dl { display: flex; align-items: center; justify-content: center; gap: 10px; padding: 14px; border-radius: 50px; font-weight: 700; text-transform: uppercase; font-size: 0.9rem; transition: all 0.3s ease; text-decoration: none !important; border: none; }
.btn-google-play { background: #202124; color: #ffffff; }
.btn-apk-direct { background: var(--bulma-primary); color: #ffffff; }
.btn-mod-apk { background: #f4b400; color: #121212; }
.btn-app-dl:hover { transform: translateY(-3px); box-shadow: 0 6px 15px rgba(0,0,0,0.1); }
